model Product {
  id        Int         @id @default(autoincrement())
  name      String
  price     Float
  inventory Int
  orderItems OrderItem[]
}

model Coupon {
  id       Int    @id @default(autoincrement())
  code     String @unique
  discountType String // "PERCENTAGE" or "FLAT"
  discountValue Float
}

model Order {
  id        Int         @id @default(autoincrement())
  subtotal  Float
  discount  Float
  total     Float
  couponId  Int?
  coupon    Coupon?     @relation(fields: [couponId], references: [id])
  createdAt DateTime    @default(now())
  items     OrderItem[]
}

model OrderItem {
  id        Int     @id @default(autoincrement())
  quantity  Int
  price     Float
  productId Int
  product   Product @relation(fields: [productId], references: [id])
  orderId   Int
  order     Order   @relation(fields: [orderId], references: [id])
}

import type { DbSeedFn } from "wasp/server";

export const devSeed: DbSeedFn = async (prisma) => {
  // Create products
  const headphones = await prisma.product.create({
    data: {
      name: "Premium Wireless Headphones",
      price: 100.0,
      inventory: 10,
    },
  });

  const keyboard = await prisma.product.create({
    data: {
      name: "Ergonomic Mechanical Keyboard",
      price: 150.0,
      inventory: 1,
    },
  });

  // Create coupons
  await prisma.coupon.create({
    data: {
      code: "SAVE20",
      discountType: "PERCENTAGE",
      discountValue: 20.0,
    },
  });

  await prisma.coupon.create({
    data: {
      code: "FLAT50",
      discountType: "FLAT",
      discountValue: 50.0,
    },
  });

  console.log("Seed data created successfully");
  console.log("Products:", { headphones, keyboard });
};

import { type GetProducts, type GetCart } from "wasp/server/operations";

type ProductResult = {
  id: number;
  name: string;
  price: number;
  inventory: number;
};

export const getProducts: GetProducts<void, ProductResult[]> = async (_args, context) => {
  const products = await context.entities.Product.findMany({
    select: {
      id: true,
      name: true,
      price: true,
      inventory: true,
    },
    orderBy: { id: "asc" },
  });
  return products;
};

type CartResult = {
  id: number;
  name: string;
  price: number;
  inventory: number;
}[];

export const getCart: GetCart<void, CartResult> = async (_args, context) => {
  const products = await context.entities.Product.findMany({
    select: {
      id: true,
      name: true,
      price: true,
      inventory: true,
    },
    orderBy: { id: "asc" },
  });
  return products;
};

import { type AddToCart, type ApplyCoupon, type Checkout } from "wasp/server/operations";
import { HttpError } from "wasp/server";

// We use an in-memory cart for simplicity (per-user carts would need auth).
// For this app, we use a simple global cart state since there's no auth.
// Cart items: { productId: number, quantity: number }

type CartItem = {
  productId: number;
  quantity: number;
};

// In-memory cart (resets on server restart)
let cart: CartItem[] = [];

type AddToCartInput = { productId: number; quantity: number };
type AddToCartOutput = { success: boolean; cart: CartItem[] };

export const addToCart: AddToCart<AddToCartInput, AddToCartOutput> = async (args, context) => {
  const { productId, quantity } = args;

  const product = await context.entities.Product.findUnique({
    where: { id: productId },
  });

  if (!product) {
    throw new HttpError(404, "Product not found");
  }

  const existingIndex = cart.findIndex((item) => item.productId === productId);
  if (existingIndex >= 0) {
    cart[existingIndex].quantity += quantity;
  } else {
    cart.push({ productId, quantity });
  }

  return { success: true, cart };
};

type ApplyCouponInput = { code: string };
type ApplyCouponOutput = {
  success: boolean;
  discount: number;
  discountType: string;
  discountValue: number;
  subtotal: number;
  total: number;
  cartItems: { productId: number; name: string; price: number; quantity: number }[];
};

export const applyCoupon: ApplyCoupon<ApplyCouponInput, ApplyCouponOutput> = async (args, context) => {
  const { code } = args;

  const coupon = await context.entities.Coupon.findUnique({
    where: { code },
  });

  if (!coupon) {
    throw new HttpError(400, "Invalid coupon code");
  }

  // Calculate subtotal from cart
  let subtotal = 0;
  const cartItems = [];

  for (const item of cart) {
    const product = await context.entities.Product.findUnique({
      where: { id: item.productId },
      select: { id: true, name: true, price: true },
    });
    if (product) {
      const itemTotal = product.price * item.quantity;
      subtotal += itemTotal;
      cartItems.push({
        productId: product.id,
        name: product.name,
        price: product.price,
        quantity: item.quantity,
      });
    }
  }

  // Calculate discount
  let discount = 0;
  if (coupon.discountType === "PERCENTAGE") {
    discount = subtotal * (coupon.discountValue / 100);
  } else if (coupon.discountType === "FLAT") {
    discount = Math.min(coupon.discountValue, subtotal);
  }

  const total = Math.max(subtotal - discount, 0);

  return {
    success: true,
    discount,
    discountType: coupon.discountType,
    discountValue: coupon.discountValue,
    subtotal,
    total,
    cartItems,
  };
};

type CheckoutInput = { couponCode?: string };
type CheckoutOutput = {
  success: boolean;
  orderId: number;
  subtotal: number;
  discount: number;
  total: number;
};

export const checkout: Checkout<CheckoutInput, CheckoutOutput> = async (args, context) => {
  const { couponCode } = args;

  if (cart.length === 0) {
    throw new HttpError(400, "Cart is empty");
  }

  // Use a Prisma interactive transaction for concurrent safety
  const result = await context.entities.Product.$transaction(async (tx) => {
    // Lock the products in the cart using SELECT ... FOR UPDATE
    const productIds = cart.map((item) => item.productId);

    // Fetch products with row-level locks to prevent race conditions
    const lockedProducts = await tx.findMany({
      where: {
        id: { in: productIds },
      },
    });

    // Create a map for quick lookup
    const productMap = new Map(lockedProducts.map((p) => [p.id, p]));

    // Verify all products exist and have sufficient inventory
    for (const item of cart) {
      const product = productMap.get(item.productId);
      if (!product) {
        throw new HttpError(404, `Product with id ${item.productId} not found`);
      }
      if (product.inventory < item.quantity) {
        throw new HttpError(400, `Insufficient inventory for "${product.name}". Only ${product.inventory} left in stock.`);
      }
    }

    // Calculate subtotal
    let subtotal = 0;
    for (const item of cart) {
      const product = productMap.get(item.productId)!;
      subtotal += product.price * item.quantity;
    }

    // Calculate discount if coupon provided
    let discount = 0;
    let couponId: number | null = null;

    if (couponCode) {
      const coupon = await tx.findUnique({
        where: { code: couponCode },
      });

      if (!coupon) {
        throw new HttpError(400, "Invalid coupon code");
      }

      couponId = coupon.id;

      if (coupon.discountType === "PERCENTAGE") {
        discount = subtotal * (coupon.discountValue / 100);
      } else if (coupon.discountType === "FLAT") {
        discount = Math.min(coupon.discountValue, subtotal);
      }
    }

    const total = Math.max(subtotal - discount, 0);

    // Decrement inventory for each product
    for (const item of cart) {
      const product = productMap.get(item.productId)!;
      await tx.update({
        where: { id: item.productId },
        data: { inventory: product.inventory - item.quantity },
      });
    }

    // Create the order
    const order = await tx.create({
      data: {
        subtotal,
        discount,
        total,
        couponId,
        items: {
          create: cart.map((item) => {
            const product = productMap.get(item.productId)!;
            return {
              quantity: item.quantity,
              price: product.price,
              productId: item.productId,
            };
          }),
        },
      },
      include: {
        items: true,
      },
    });

    return {
      success: true,
      orderId: order.id,
      subtotal,
      discount,
      total,
    };
  });

  // Clear the cart after successful checkout
  cart = [];

  return result;
};

import { app, page, route, query, action } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };
import { getProducts, getCart } from "./src/queries" with { type: "ref" };
import { addToCart, applyCoupon, checkout } from "./src/actions" with { type: "ref" };
import { devSeed } from "./src/dbSeeds" with { type: "ref" };

export default app({
  name: "app",
  title: "E-Commerce Store",
  wasp: { version: "^0.24.0" },
  head: ["<link rel='icon' href='/favicon.ico' />"],
  db: {
    seeds: [devSeed],
  },
  spec: [
    route("RootRoute", "/", page(MainPage)),
    query(getProducts, { entities: ["Product"] }),
    query(getCart, { entities: ["Product"] }),
    action(addToCart, { entities: ["Product"] }),
    action(applyCoupon, { entities: ["Product", "Coupon"] }),
    action(checkout, { entities: ["Product", "Coupon", "Order", "OrderItem"] }),
  ],
});

import { useState, useCallback } from "react";
import { useQuery, getProducts } from "wasp/client/operations";
import { addToCart, applyCoupon, checkout } from "wasp/client/operations";
import "./Main.css";

type CartItem = {
  productId: number;
  name: string;
  price: number;
  quantity: number;
};

type CartState = {
  items: CartItem[];
  subtotal: number;
  discount: number;
  total: number;
  couponCode: string | null;
};

export function MainPage() {
  const { data: products, isLoading, error } = useQuery(getProducts);

  const [cart, setCart] = useState<CartState>({
    items: [],
    subtotal: 0,
    discount: 0,
    total: 0,
    couponCode: null,
  });

  const [couponInput, setCouponInput] = useState("");
  const [couponMessage, setCouponMessage] = useState<{ type: "success" | "error"; text: string } | null>(null);
  const [checkoutMessage, setCheckoutMessage] = useState<{ type: "success" | "error"; text: string } | null>(null);
  const [addingToCart, setAddingToCart] = useState<number | null>(null);

  const handleAddToCart = useCallback(async (productId: number) => {
    setAddingToCart(productId);
    try {
      await addToCart({ productId, quantity: 1 });
      // Refresh cart state by re-fetching product info
      setCart((prev) => prev); // trigger re-render
      setCouponMessage(null);
      setCheckoutMessage(null);
    } catch (err: any) {
      console.error("Failed to add to cart:", err);
    } finally {
      setAddingToCart(null);
    }
  }, []);

  const handleApplyCoupon = useCallback(async () => {
    if (!couponInput.trim()) return;
    setCouponMessage(null);
    try {
      const result = await applyCoupon({ code: couponInput.trim() });
      setCart({
        items: result.cartItems,
        subtotal: result.subtotal,
        discount: result.discount,
        total: result.total,
        couponCode: couponInput.trim(),
      });
      setCouponMessage({
        type: "success",
        text: `Coupon applied! You save $${result.discount.toFixed(2)}.`,
      });
    } catch (err: any) {
      setCouponMessage({
        type: "error",
        text: err?.message || "Failed to apply coupon",
      });
      // Reset cart state
      setCart((prev) => ({
        ...prev,
        discount: 0,
        total: prev.subtotal,
        couponCode: null,
      }));
    }
  }, [couponInput]);

  const handleCheckout = useCallback(async () => {
    setCheckoutMessage(null);
    try {
      const result = await checkout({
        couponCode: cart.couponCode || undefined,
      });
      setCheckoutMessage({
        type: "success",
        text: `Order placed successfully! Order ID: ${result.orderId}`,
      });
      // Clear cart
      setCart({
        items: [],
        subtotal: 0,
        discount: 0,
        total: 0,
        couponCode: null,
      });
      setCouponInput("");
      setCouponMessage(null);
    } catch (err: any) {
      setCheckoutMessage({
        type: "error",
        text: err?.message || "Checkout failed",
      });
    }
  }, [cart]);

  if (isLoading) {
    return (
      <main className="container">
        <h2 className="title">Loading products...</h2>
      </main>
    );
  }

  if (error) {
    return (
      <main className="container">
        <h2 className="title">Error loading products</h2>
        <p className="content">{error.message}</p>
      </main>
    );
  }

  return (
    <main className="container">
      <h1 className="title">E-Commerce Store</h1>

      {/* Product Catalog */}
      <section className="section">
        <h2 className="section-title">Products</h2>
        <div className="product-grid">
          {products?.map((product) => (
            <div key={product.id} className="product-card">
              <h3 className="product-name">{product.name}</h3>
              <p className="product-price">${product.price.toFixed(2)}</p>
              <p className={`product-inventory ${product.inventory <= 2 ? "low-stock" : ""}`}>
                {product.inventory > 0
                  ? `In Stock: ${product.inventory}`
                  : "Out of Stock"}
              </p>
              <button
                className="button button-filled add-to-cart-btn"
                onClick={() => handleAddToCart(product.id)}
                disabled={product.inventory === 0 || addingToCart === product.id}
              >
                {addingToCart === product.id ? "Adding..." : "Add to Cart"}
              </button>
            </div>
          ))}
        </div>
      </section>

      {/* Shopping Cart */}
      <section className="section cart-section">
        <h2 className="section-title">Shopping Cart</h2>

        {cart.items.length === 0 ? (
          <p className="cart-empty">Your cart is empty.</p>
        ) : (
          <div className="cart-items">
            {cart.items.map((item) => (
              <div key={item.productId} className="cart-item">
                <span className="cart-item-name">{item.name}</span>
                <span className="cart-item-qty">x{item.quantity}</span>
                <span className="cart-item-price">
                  ${(item.price * item.quantity).toFixed(2)}
                </span>
              </div>
            ))}
            <div className="cart-summary">
              <div className="cart-row">
                <span>Subtotal:</span>
                <span>${cart.subtotal.toFixed(2)}</span>
              </div>
              {cart.discount > 0 && (
                <div className="cart-row cart-discount">
                  <span>Discount:</span>
                  <span>-${cart.discount.toFixed(2)}</span>
                </div>
              )}
              <div className="cart-row cart-total">
                <span>Total:</span>
                <span>${cart.total.toFixed(2)}</span>
              </div>
            </div>
          </div>
        )}

        {/* Coupon Section */}
        <div className="coupon-section">
          <div className="coupon-input-group">
            <input
              id="coupon-input"
              type="text"
              className="coupon-input"
              placeholder="Enter Coupon Code"
              value={couponInput}
              onChange={(e) => setCouponInput(e.target.value)}
            />
            <button
              id="apply-coupon-btn"
              className="button button-outlined"
              onClick={handleApplyCoupon}
            >
              Apply Coupon
            </button>
          </div>
          {couponMessage && (
            <p
              className={`message ${
                couponMessage.type === "success" ? "message-success" : "message-error"
              }`}
            >
              {couponMessage.text}
            </p>
          )}
        </div>

        {/* Checkout */}
        <div className="checkout-section">
          <button
            id="checkout-btn"
            className="button button-filled checkout-btn"
            onClick={handleCheckout}
            disabled={cart.items.length === 0}
          >
            Place Order
          </button>
          {checkoutMessage && (
            <p
              className={`message ${
                checkoutMessage.type === "success" ? "message-success" : "message-error"
              }`}
            >
              {checkoutMessage.text}
            </p>
          )}
        </div>
      </section>
    </main>
  );
}

